pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this));
        // Transfer ownership to newOwner
        c.transferOwnership(newOwner);
        // As newOwner, call owned()
        vm.prank(newOwner);
        c.owned();
        // The owner should still be newOwner (the reference requires msg.sender == owner, so it succeeds and owner unchanged)
        assertTrue(c.owner() == newOwner);
    }
}

