// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;
    function setUp() public { 
        c = new C(); 
        initialOwner = c.owner();
    }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        // Try to transfer ownership -- in reference this would change owner, in bug it won't
        // But we need a rule that distinguishes them. Simpler: just call owned() as caller.
        // The bug is that transferOwnership does nothing, so owner never changes.
        // General rule: After any sequence of calls ending with owned(), owner unchanged.
        // To demonstrate, we first call transferOwnership to try to change it.
        vm.prank(initialOwner); // Must be owner to call transferOwnership
        c.transferOwnership(caller);
        // Now call owned() irrespective of who caller is -- if bug, owner still initialOwner.
        vm.prank(caller);
        c.owned();
        assertTrue(c.owner() == initialOwner);
    }
}

